INSERT INTO `t_sys_param` VALUES ('100132', '404', 'standardPoints', '是否使用标准点位ID', 'true', '标准点位ID，巡视主机和边缘节点使用统一的点位ID，不使用自增ID，此情况一个测点只可以绑定一个巡视设备，true或false', '{\"rule\":\"^(true|false)$\",\"msg\":\"只能填 true 或 false\"}');
